    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"المعطيات","math":"<span dir=\"ltr\" class=\"expr pt\">IĴK</span> و <span dir=\"ltr\" class=\"expr pt\">KĴL</span> متتامّتان  و  <span dir=\"ltr\" class=\"expr pt\">IĴK = 45°</span>"},{"quoi":"الاختيار","math":"المطلوب : حساب قيس الزاوية <span dir=\"ltr\" class=\"expr pt\">KĴL.</span> نختار الزاويتان المتتامّتان لأنّ معطياتها متوفّرة <span dir=\"ltr\" class=\"expr pt\">: IĴK</span> و <span dir=\"ltr\" class=\"expr pt\">KĴL</span> متتامّتان  و  <span dir=\"ltr\" class=\"expr pt\">IĴK = 45°.</span> و لماذا لا مجموع زوايا المثلّث ؟ لأنّها تحتاج مثلّثا، و لا مثلّث في هذا الشّكل."},{"quoi":"القاعدة","math":"زاويتان متتامّتان مجموع قيسيهما <span dir=\"ltr\" class=\"expr\">90°</span>"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">IĴK</span> و <span dir=\"ltr\" class=\"expr pt\">KĴL</span> متتامّتان  و  <span dir=\"ltr\" class=\"expr pt\">IĴK = 45°</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">KĴL = 90° - 45° = 45°</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr pt\">KĴL = 45°</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"المعطيات","math":"<span dir=\"ltr\" class=\"expr pt\">AÔB</span> و <span dir=\"ltr\" class=\"expr pt\">BÔC</span> متتامّتان  و  <span dir=\"ltr\" class=\"expr pt\">BÔC = 33°</span>"},{"quoi":"الاختيار","math":"المطلوب : حساب قيس الزاوية <span dir=\"ltr\" class=\"expr pt\">AÔB.</span> نختار الزاويتان المتتامّتان لأنّ معطياتها متوفّرة <span dir=\"ltr\" class=\"expr pt\">: BÔC</span> و <span dir=\"ltr\" class=\"expr pt\">AÔB</span> متتامّتان  و  <span dir=\"ltr\" class=\"expr pt\">BÔC = 33°.</span> و لماذا لا مجموع زوايا المثلّث ؟ لأنّها تحتاج مثلّثا، و لا مثلّث في هذا الشّكل."},{"quoi":"القاعدة","math":"زاويتان متتامّتان مجموع قيسيهما <span dir=\"ltr\" class=\"expr\">90°</span>"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">BÔC</span> و <span dir=\"ltr\" class=\"expr pt\">AÔB</span> متتامّتان  و  <span dir=\"ltr\" class=\"expr pt\">BÔC = 33°</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">AÔB = 90° - 33° = 57°</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr pt\">AÔB = 57°</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"المعطيات","math":"<span dir=\"ltr\" class=\"expr pt\">AÔB</span> و <span dir=\"ltr\" class=\"expr pt\">BÔC</span> متتامّتان  و  <span dir=\"ltr\" class=\"expr pt\">BÔC = 49°</span>"},{"quoi":"الاختيار","math":"المطلوب : حساب قيس الزاوية <span dir=\"ltr\" class=\"expr pt\">AÔB.</span> نختار الزاويتان المتتامّتان لأنّ معطياتها متوفّرة <span dir=\"ltr\" class=\"expr pt\">: BÔC</span> و <span dir=\"ltr\" class=\"expr pt\">AÔB</span> متتامّتان  و  <span dir=\"ltr\" class=\"expr pt\">BÔC = 49°.</span> و لماذا لا مجموع زوايا المثلّث ؟ لأنّها تحتاج مثلّثا، و لا مثلّث في هذا الشّكل."},{"quoi":"القاعدة","math":"زاويتان متتامّتان مجموع قيسيهما <span dir=\"ltr\" class=\"expr\">90°</span>"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">BÔC</span> و <span dir=\"ltr\" class=\"expr pt\">AÔB</span> متتامّتان  و  <span dir=\"ltr\" class=\"expr pt\">BÔC = 49°</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">AÔB = 90° - 49° = 41°</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr pt\">AÔB = 41°</span>"},{"quoi":"","math":"<b>4)</b>"},{"quoi":"المعطيات","math":"<span dir=\"ltr\" class=\"expr pt\">IĴK</span> و <span dir=\"ltr\" class=\"expr pt\">KĴL</span> متتامّتان  و  <span dir=\"ltr\" class=\"expr pt\">IĴK = 58°</span>"},{"quoi":"الاختيار","math":"المطلوب : حساب قيس الزاوية <span dir=\"ltr\" class=\"expr pt\">KĴL.</span> نختار الزاويتان المتتامّتان لأنّ معطياتها متوفّرة <span dir=\"ltr\" class=\"expr pt\">: IĴK</span> و <span dir=\"ltr\" class=\"expr pt\">KĴL</span> متتامّتان  و  <span dir=\"ltr\" class=\"expr pt\">IĴK = 58°.</span> و لماذا لا مجموع زوايا المثلّث ؟ لأنّها تحتاج مثلّثا، و لا مثلّث في هذا الشّكل."},{"quoi":"القاعدة","math":"زاويتان متتامّتان مجموع قيسيهما <span dir=\"ltr\" class=\"expr\">90°</span>"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">IĴK</span> و <span dir=\"ltr\" class=\"expr pt\">KĴL</span> متتامّتان  و  <span dir=\"ltr\" class=\"expr pt\">IĴK = 58°</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">KĴL = 90° - 58° = 32°</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr pt\">KĴL = 32°</span>"}],
