    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"المعطيات","math":"<span dir=\"ltr\" class=\"expr pt\">BÂC = 90°</span>  و  <span dir=\"ltr\" class=\"expr pt\">AB̂C = 38°</span>"},{"quoi":"الاختيار","math":"المطلوب : حساب قيس الزاوية <span dir=\"ltr\" class=\"expr pt\">AĈB.</span> نختار مجموع زوايا المثلّث لأنّ معطياتها متوفّرة : في المثلّث <span dir=\"ltr\" class=\"expr pt\">ABC</span>  و  <span dir=\"ltr\" class=\"expr pt\">BÂC = 90°</span>  و  <span dir=\"ltr\" class=\"expr pt\">AB̂C = 38°.</span> و لماذا لا المنصّف ؟ لأنّها تحتاج منصّفا، و لا منصّف في الشّكل."},{"quoi":"القاعدة","math":"مجموع قيسات زوايا مثلّث يساوي <span dir=\"ltr\" class=\"expr\">180°</span>"},{"quoi":"نطبّق","math":"في المثلّث <span dir=\"ltr\" class=\"expr pt\">ABC</span>  و  <span dir=\"ltr\" class=\"expr pt\">BÂC = 90°</span>  و  <span dir=\"ltr\" class=\"expr pt\">AB̂C = 38°</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">AĈB = 180° - (90° + 38°) = 52°</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr pt\">AĈB = 52°</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"المعطيات","math":"<span dir=\"ltr\" class=\"expr pt\">BÂC = 90°</span>  و  <span dir=\"ltr\" class=\"expr pt\">AB̂C = 36°</span>  و  <span dir=\"ltr\" class=\"expr pt\">[BO)</span> هو منصّف الزاوية <span dir=\"ltr\" class=\"expr pt\">AB̂C</span>  و  <span dir=\"ltr\" class=\"expr pt\">[CO)</span> هو منصّف الزاوية <span dir=\"ltr\" class=\"expr pt\">AĈB</span>"},{"quoi":"الاختيار","math":"المطلوب : حساب قيس الزاوية <span dir=\"ltr\" class=\"expr pt\">BÔC.</span> نختار المنصّف لأنّ معطياتها متوفّرة <span dir=\"ltr\" class=\"expr pt\">: [BO)</span> هو منصّف الزاوية <span dir=\"ltr\" class=\"expr pt\">AB̂C</span>  و  <span dir=\"ltr\" class=\"expr pt\">AB̂C = 36°.</span> و لماذا لا الزاويتان المتقابلتان بالرأس ؟ لأنّها تحتاج زاويتين متقابلتين بالرأس، و لا وجود لهما هنا."},{"quoi":"القاعدة","math":"منصّف زاوية يقسمها إلى زاويتين متقايستين، قيس كلّ منهما نصف قيسها"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">[BO)</span> هو منصّف الزاوية <span dir=\"ltr\" class=\"expr pt\">AB̂C</span>  و  <span dir=\"ltr\" class=\"expr pt\">AB̂C = 36°</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">CB̂O = 36° : 2 = 18°</span>"},{"quoi":"القاعدة","math":"مجموع قيسات زوايا مثلّث يساوي <span dir=\"ltr\" class=\"expr\">180°</span>"},{"quoi":"نطبّق","math":"في المثلّث <span dir=\"ltr\" class=\"expr pt\">ABC</span>  و  <span dir=\"ltr\" class=\"expr pt\">BÂC = 90°</span>  و  <span dir=\"ltr\" class=\"expr pt\">AB̂C = 36°</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">AĈB = 180° - (90° + 36°) = 54°</span>"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">[CO)</span> هو منصّف الزاوية <span dir=\"ltr\" class=\"expr pt\">AĈB</span>  و  <span dir=\"ltr\" class=\"expr pt\">AĈB = 54°</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">BĈO = 54° : 2 = 27°</span>"},{"quoi":"نطبّق","math":"في المثلّث <span dir=\"ltr\" class=\"expr pt\">OBC</span>  و  <span dir=\"ltr\" class=\"expr pt\">CB̂O = 18°</span>  و  <span dir=\"ltr\" class=\"expr pt\">BĈO = 27°</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">BÔC = 180° - (18° + 27°) = 135°</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr pt\">BÔC = 135°</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"المعطيات","math":"<span dir=\"ltr\" class=\"expr pt\">BÂC = 41°</span>  و  <span dir=\"ltr\" class=\"expr pt\">AB̂C = 82°</span>"},{"quoi":"الاختيار","math":"المطلوب : حساب قيس الزاوية <span dir=\"ltr\" class=\"expr pt\">AĈB.</span> نختار مجموع زوايا المثلّث لأنّ معطياتها متوفّرة : في المثلّث <span dir=\"ltr\" class=\"expr pt\">ABC</span>  و  <span dir=\"ltr\" class=\"expr pt\">BÂC = 41°</span>  و  <span dir=\"ltr\" class=\"expr pt\">AB̂C = 82°.</span> و لماذا لا المنصّف ؟ لأنّها تحتاج منصّفا، و لا منصّف في الشّكل."},{"quoi":"القاعدة","math":"مجموع قيسات زوايا مثلّث يساوي <span dir=\"ltr\" class=\"expr\">180°</span>"},{"quoi":"نطبّق","math":"في المثلّث <span dir=\"ltr\" class=\"expr pt\">ABC</span>  و  <span dir=\"ltr\" class=\"expr pt\">BÂC = 41°</span>  و  <span dir=\"ltr\" class=\"expr pt\">AB̂C = 82°</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">AĈB = 180° - (41° + 82°) = 57°</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr pt\">AĈB = 57°</span>"},{"quoi":"","math":"<b>4)</b>"},{"quoi":"المعطيات","math":"<span dir=\"ltr\" class=\"expr pt\">BÂC = 90°</span>  و  <span dir=\"ltr\" class=\"expr pt\">AB̂C = 49°</span>"},{"quoi":"الاختيار","math":"المطلوب : حساب قيس الزاوية <span dir=\"ltr\" class=\"expr pt\">AĈB.</span> نختار مجموع زوايا المثلّث لأنّ معطياتها متوفّرة : في المثلّث <span dir=\"ltr\" class=\"expr pt\">ABC</span>  و  <span dir=\"ltr\" class=\"expr pt\">BÂC = 90°</span>  و  <span dir=\"ltr\" class=\"expr pt\">AB̂C = 49°.</span> و لماذا لا المنصّف ؟ لأنّها تحتاج منصّفا، و لا منصّف في الشّكل."},{"quoi":"القاعدة","math":"مجموع قيسات زوايا مثلّث يساوي <span dir=\"ltr\" class=\"expr\">180°</span>"},{"quoi":"نطبّق","math":"في المثلّث <span dir=\"ltr\" class=\"expr pt\">ABC</span>  و  <span dir=\"ltr\" class=\"expr pt\">BÂC = 90°</span>  و  <span dir=\"ltr\" class=\"expr pt\">AB̂C = 49°</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">AĈB = 180° - (90° + 49°) = 41°</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr pt\">AĈB = 41°</span>"}],
