    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"المعطيات","math":"<span dir=\"ltr\" class=\"expr pt\">BÂC = 61°</span>  و  <span dir=\"ltr\" class=\"expr pt\">AB̂C = 79°</span>"},{"quoi":"الاختيار","math":"المطلوب : حساب قيس الزاوية <span dir=\"ltr\" class=\"expr pt\">AĈB.</span> نختار مجموع زوايا المثلّث لأنّ معطياتها متوفّرة : في المثلّث <span dir=\"ltr\" class=\"expr pt\">ABC</span>  و  <span dir=\"ltr\" class=\"expr pt\">BÂC = 61°</span>  و  <span dir=\"ltr\" class=\"expr pt\">AB̂C = 79°.</span> و لماذا لا المنصّف ؟ لأنّها تحتاج منصّفا، و لا منصّف في الشّكل."},{"quoi":"القاعدة","math":"مجموع قيسات زوايا مثلّث يساوي <span dir=\"ltr\" class=\"expr\">180°</span>"},{"quoi":"نطبّق","math":"في المثلّث <span dir=\"ltr\" class=\"expr pt\">ABC</span>  و  <span dir=\"ltr\" class=\"expr pt\">BÂC = 61°</span>  و  <span dir=\"ltr\" class=\"expr pt\">AB̂C = 79°</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">AĈB = 180° - (61° + 79°) = 40°</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr pt\">AĈB = 40°</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"المعطيات","math":"<span dir=\"ltr\" class=\"expr pt\">BÂC = 90°</span>  و  <span dir=\"ltr\" class=\"expr pt\">AB̂C = 40°</span>  و  <span dir=\"ltr\" class=\"expr pt\">[BO)</span> هو منصّف الزاوية <span dir=\"ltr\" class=\"expr pt\">AB̂C</span>  و  <span dir=\"ltr\" class=\"expr pt\">[CO)</span> هو منصّف الزاوية <span dir=\"ltr\" class=\"expr pt\">AĈB</span>"},{"quoi":"الاختيار","math":"المطلوب : حساب قيس الزاوية <span dir=\"ltr\" class=\"expr pt\">BÔC.</span> نختار المنصّف لأنّ معطياتها متوفّرة <span dir=\"ltr\" class=\"expr pt\">: [BO)</span> هو منصّف الزاوية <span dir=\"ltr\" class=\"expr pt\">AB̂C</span>  و  <span dir=\"ltr\" class=\"expr pt\">AB̂C = 40°.</span> و لماذا لا الزاويتان المتقابلتان بالرأس ؟ لأنّها تحتاج زاويتين متقابلتين بالرأس، و لا وجود لهما هنا."},{"quoi":"القاعدة","math":"منصّف زاوية يقسمها إلى زاويتين متقايستين، قيس كلّ منهما نصف قيسها"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">[BO)</span> هو منصّف الزاوية <span dir=\"ltr\" class=\"expr pt\">AB̂C</span>  و  <span dir=\"ltr\" class=\"expr pt\">AB̂C = 40°</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">CB̂O = 40° : 2 = 20°</span>"},{"quoi":"القاعدة","math":"مجموع قيسات زوايا مثلّث يساوي <span dir=\"ltr\" class=\"expr\">180°</span>"},{"quoi":"نطبّق","math":"في المثلّث <span dir=\"ltr\" class=\"expr pt\">ABC</span>  و  <span dir=\"ltr\" class=\"expr pt\">BÂC = 90°</span>  و  <span dir=\"ltr\" class=\"expr pt\">AB̂C = 40°</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">AĈB = 180° - (90° + 40°) = 50°</span>"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">[CO)</span> هو منصّف الزاوية <span dir=\"ltr\" class=\"expr pt\">AĈB</span>  و  <span dir=\"ltr\" class=\"expr pt\">AĈB = 50°</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">BĈO = 50° : 2 = 25°</span>"},{"quoi":"نطبّق","math":"في المثلّث <span dir=\"ltr\" class=\"expr pt\">OBC</span>  و  <span dir=\"ltr\" class=\"expr pt\">CB̂O = 20°</span>  و  <span dir=\"ltr\" class=\"expr pt\">BĈO = 25°</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">BÔC = 180° - (20° + 25°) = 135°</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr pt\">BÔC = 135°</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"المعطيات","math":"<span dir=\"ltr\" class=\"expr pt\">BÂC = 90°</span>  و  <span dir=\"ltr\" class=\"expr pt\">AB̂C = 65°</span>"},{"quoi":"الاختيار","math":"المطلوب : حساب قيس الزاوية <span dir=\"ltr\" class=\"expr pt\">AĈB.</span> نختار مجموع زوايا المثلّث لأنّ معطياتها متوفّرة : في المثلّث <span dir=\"ltr\" class=\"expr pt\">ABC</span>  و  <span dir=\"ltr\" class=\"expr pt\">BÂC = 90°</span>  و  <span dir=\"ltr\" class=\"expr pt\">AB̂C = 65°.</span> و لماذا لا المنصّف ؟ لأنّها تحتاج منصّفا، و لا منصّف في الشّكل."},{"quoi":"القاعدة","math":"مجموع قيسات زوايا مثلّث يساوي <span dir=\"ltr\" class=\"expr\">180°</span>"},{"quoi":"نطبّق","math":"في المثلّث <span dir=\"ltr\" class=\"expr pt\">ABC</span>  و  <span dir=\"ltr\" class=\"expr pt\">BÂC = 90°</span>  و  <span dir=\"ltr\" class=\"expr pt\">AB̂C = 65°</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">AĈB = 180° - (90° + 65°) = 25°</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr pt\">AĈB = 25°</span>"},{"quoi":"","math":"<b>4)</b>"},{"quoi":"المعطيات","math":"<span dir=\"ltr\" class=\"expr pt\">BÂC = 52°</span>  و  <span dir=\"ltr\" class=\"expr pt\">AB̂C = 82°</span>"},{"quoi":"الاختيار","math":"المطلوب : حساب قيس الزاوية <span dir=\"ltr\" class=\"expr pt\">AĈB.</span> نختار مجموع زوايا المثلّث لأنّ معطياتها متوفّرة : في المثلّث <span dir=\"ltr\" class=\"expr pt\">ABC</span>  و  <span dir=\"ltr\" class=\"expr pt\">BÂC = 52°</span>  و  <span dir=\"ltr\" class=\"expr pt\">AB̂C = 82°.</span> و لماذا لا المنصّف ؟ لأنّها تحتاج منصّفا، و لا منصّف في الشّكل."},{"quoi":"القاعدة","math":"مجموع قيسات زوايا مثلّث يساوي <span dir=\"ltr\" class=\"expr\">180°</span>"},{"quoi":"نطبّق","math":"في المثلّث <span dir=\"ltr\" class=\"expr pt\">ABC</span>  و  <span dir=\"ltr\" class=\"expr pt\">BÂC = 52°</span>  و  <span dir=\"ltr\" class=\"expr pt\">AB̂C = 82°</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">AĈB = 180° - (52° + 82°) = 46°</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr pt\">AĈB = 46°</span>"}],
